#!/usr/bin/env python3
"""Install the MMFR Pro / Explore dual-view redesign.

Put this file beside index.html in the MMFR repository and run:
    python install_mmfr_pro_explore.py
"""

from base64 import b64decode
from datetime import datetime, timezone
from io import BytesIO
from pathlib import Path, PurePosixPath
from tempfile import TemporaryDirectory
from zipfile import ZIP_DEFLATED, ZipFile
import os


ROOT = Path.cwd().resolve()
FILES = ['README.md', 'index.html', 'uk.html', 'us.html', 'europe.html', 'asia.html', 'crypto.html', 'trends.html', 'css/styles.css', 'js/core.js', 'js/data.js', 'js/markets.js', 'js/page.js', 'js/ui.js', 'assets/pro/home-betta.webp', 'assets/pro/uk-atlantic-salmon.webp', 'assets/pro/us-striped-bass.webp', 'assets/pro/europe-sea-bass.webp', 'assets/pro/asia-koi.webp', 'assets/pro/crypto-blue-discus.webp', 'assets/pro/trends-anglerfish.webp']
PAYLOAD = """"""


for marker in ("index.html", "css/styles.css", "js/page.js", "js/ui.js"):
    if not (ROOT / marker).is_file():
        raise SystemExit(
            "This is not the MMFR repo root. Put the installer beside index.html "
            "and run it from that folder."
        )

payload_bytes = b64decode(PAYLOAD.encode("ascii"), validate=True)
with ZipFile(BytesIO(payload_bytes), "r") as archive:
    names = archive.namelist()
    if names != FILES:
        raise SystemExit("The installer payload did not pass its manifest check.")
    for name in names:
        pure = PurePosixPath(name)
        if pure.is_absolute() or ".." in pure.parts:
            raise SystemExit("The installer payload contains an unsafe path.")
        archive.read(name)

stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
backup = ROOT.parent / ("MMFR_before_pro_explore_" + stamp + ".zip")
with ZipFile(backup, "w", ZIP_DEFLATED, compresslevel=9) as archive:
    for relative_path in FILES:
        current = ROOT / relative_path
        if current.is_file():
            archive.write(current, relative_path)

with TemporaryDirectory(prefix=".mmfr-pro-explore-", dir=ROOT) as temp_name:
    stage = Path(temp_name)
    with ZipFile(BytesIO(payload_bytes), "r") as archive:
        archive.extractall(stage)
    for relative_path in FILES:
        source = stage / relative_path
        target = ROOT / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        os.replace(source, target)

print("MMFR Pro / Explore installed successfully.")
print("Backup created outside the repo:", backup)
print("Review with: git diff --stat")
print('Suggested commit: git commit -m "Add Pro and Explore views"')
